with flattened_attrs as (select id, customer_id, created_at, coupon_codes, items, ship_to, transform(filter(items, i -> i.promo is not null), i -> struct(i.product_id as pid, round(i.price * 0.9, 2) as discounted_price)) as promo_lines, transform(items, i -> i.product_id) as product_ids, try_cast(attributes['weight_kg'] as double) as weight_kg, exists(coupon_codes, c -> c like 'W%') as has_welcome_code from carts where hour(created_at) between 9 and 12) select *, last_value(weight_kg) ignore nulls over (partition by customer_id order by created_at, id rows between unbounded preceding and current row) as last_known_weight_kg, avg(weight_kg) over (partition by customer_id order by cast(created_at as bigint) range between 3600 preceding and current row) as weight_kg_avg_1h, avg(weight_kg) over (partition by customer_id order by created_at, id rows between 5 preceding and current row) as weight_kg_avg_5 from flattened_attrs;
